// Search-only: compile against the temporary Capacity=1024 header, never 256.
#include "forge/board.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <iostream>
#include <random>
#include <sstream>
#include <vector>
using namespace forge;
static_assert(MoveList::Capacity>=1024,"Use the test-only enlarged header");
int geometric(const Board&b){int n=0;auto us=b.side_to_move(),them=opposite(us);auto own=b.occupied(us),enemy=b.occupied(them),occ=b.occupied();auto pawns=b.pieces(us,Pawn);while(pawns){int f=pop_lsb(pawns),to=f+pawn_push_delta(us);bool promo=relative_rank(us,f)==6;int mult=promo?4:1;if(b.piece_at(to)==Empty){n+=mult;if(relative_rank(us,f)==1&&b.piece_at(to+pawn_push_delta(us))==Empty)++n;}n+=mult*popcount(attacks::pawn(us,f)&enemy);if(b.ep_square()>=0&&(attacks::pawn(us,f)&square_bb(b.ep_square())))++n;}
for(int type=Knight;type<=King;++type){auto pieces=b.pieces(us,static_cast<PieceType>(type));while(pieces){int f=pop_lsb(pieces);Bitboard a=0;switch(type){case Knight:a=attacks::knight(f);break;case Bishop:a=attacks::bishop(f,occ);break;case Rook:a=attacks::rook(f,occ);break;case Queen:a=attacks::queen(f,occ);break;case King:a=attacks::king(f);break;}n+=popcount(a&~own);}}return n;}
std::string fen(const std::array<char,64>&a){std::ostringstream out;for(int r=7;r>=0;--r){int empty=0;for(int f=0;f<8;++f){char p=a[r*8+f];if(!p)++empty;else{if(empty)out<<empty;empty=0;out<<p;}}if(empty)out<<empty;if(r)out<<'/';}out<<" w - - 0 1";return out.str();}
int main(){std::mt19937 rng(20261115);Board board;int global=0;std::uint64_t proposed=0,accepted=0;for(int config=0;config<78;++config){int pawns=config<54?config%9:(config-54)%2;bool bottom=config<54?(config/9)%2:((config-54)/2)%2;bool targets=config>=36&&config<54;std::vector<char> inventory{'K','N','N','B','B','R','R','Q'};for(int i=0;i<pawns;++i)inventory.push_back('P');for(int i=0;i<8-pawns;++i)inventory.push_back((config<18||config>=54)?'Q':(rng()%4?'Q':"NBR"[rng()%3]));if(config>=54)inventory.erase(inventory.begin()+1,inventory.begin()+2+(config-54)/4);std::array<char,64> state{};std::vector<int> squares;bool ready=false;for(int attempt=0;attempt<10000&&!ready;++attempt){state.fill(0);squares.clear();int king=bottom?0:56;state[king]='k';state[king+1]='r';state[king+(bottom?8:-8)]='p';state[king+(bottom?9:-7)]='p';if(targets)for(int f=2;f<8;++f)state[56+f]='r';for(char p:inventory){int s;do{s=rng()%64;}while(state[s]||(p=='P'&&(rank_of(s)==0||rank_of(s)==7)));state[s]=p;squares.push_back(s);}ready=board.set_fen(fen(state));}if(!ready){std::cerr<<"cannot initialize "<<config<<'\n';return 2;}int score=geometric(board),best=score;auto best_state=state;for(int step=0;step<6000;++step){++proposed;auto trial=state;auto next=squares;int i=rng()%squares.size(),to=rng()%64,from=squares[i];char p=trial[from];if((p=='P'&&(rank_of(to)==0||rank_of(to)==7))||trial[to])continue;trial[from]=0;trial[to]=p;next[i]=to;auto f=fen(trial);if(!board.set_fen(f))continue;++accepted;int count=geometric(board);if(count>best){best=count;best_state=trial;}double temperature=step%1500<500?2.0:0.4;bool take=count>=score||std::generate_canonical<double,32>(rng)<std::exp((count-score)/temperature);if(take){state=trial;squares=next;score=count;}if(count>global){global=count;auto pseudo=board.pseudo_legal_moves();if(pseudo.size()!=static_cast<size_t>(count)){std::cerr<<"count disagreement";return 3;}std::cout<<"NEW_MAX count="<<global<<" legal="<<board.legal_moves().size()<<" fen="<<f<<'\n';}}
if(!board.set_fen(fen(best_state)))return 4;if(board.pseudo_legal_moves().size()!=static_cast<size_t>(best))return 5;std::cout<<"CONFIG "<<config<<" count="<<best<<" legal="<<board.legal_moves().size()<<" fen="<<fen(best_state)<<'\n';}
std::cout<<"DONE maximum="<<global<<" proposed="<<proposed<<" parser_accepted="<<accepted<<" seed=20261115\n";}
